SELECT tgrelid::regclass AS tbl, tgname, tgisinternal FROM pg_trigger WHERE tgrelid IN ('dashboard_actions'::regclass,'dashboard_executed_actions'::regclass,'dashboard_administrator_tasks'::regclass,'proposals'::regclass,'proposal_translations'::regclass,'proposal_notifications'::regclass);
SELECT version FROM schema_migrations ORDER BY version DESC LIMIT 5;
